import java.util.*;

import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;

import static org.junit.jupiter.api.Assertions.*;

public class Main {
    public static void main(String[] args) {
        JalankanTest.kelas(OngkirTest.class);
    }
}

class OngkirTest {
    @ParameterizedTest(name = "{0} kg ke {1} = {2}")
    @CsvSource({
        "1, dalam kota, 10000",
        "5, dalam kota, 10000",
        "2, luar kota, 30000",
        "3, luar kota, 40000"
    })
    void hitung(int kilo, String tujuan, int harapan) {
        assertEquals(harapan, Ongkir.hitung(tujuan, kilo));
    }
}

class Ongkir {
    static int hitung(String tujuan, int kilo) {
        if (tujuan.equals("dalam kota")) {
            return 10000;
        }
        return 15000 * kilo;
    }
}

