import java.util.*;

import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;

import static org.junit.jupiter.api.Assertions.*;

public class Main {
    public static void main(String[] args) {
        JalankanTest.kelas(NilaiTest.class);
    }
}

class NilaiTest {
    @ParameterizedTest(name = "skor {0} = {1}")
    @CsvSource({
        "100, A", "85, A",
        "84, B", "70, B",
        "69, C", "55, C",
        "54, D", "40, D",
        "39, E", "0, E"
    })
    void huruf(int skor, String harapan) {
        assertEquals(harapan, Nilai.huruf(skor));
    }
}

class Nilai {
    // A: 85 ke atas, B: 70 ke atas, C: 55 ke atas, D: 40 ke atas, selain itu E
    static String huruf(int skor) {
        if (skor >= 85) {
            return "A";
        } else if (skor >= 70) {
            return "B";
        } else if (skor >= 55) {
            return "C";
        } else if (skor >= 40) {
            return "D";
        }
        return "E";
    }
}
